INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-03-3-section-2-sentence-5-1','cet4-2023-03-3',104,0,'Police suspect the eggs came from a freighter that lost part of its cargo during an unusually intense storm, the worst to hit Germany''s northeastern coast since 2006.','cet4-2023-03-3-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
