INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-06-1-section-2-sentence-1-4','cet4-2023-06-1',100,3,'Well, creating fabric from cotton, which is the most abundant clothing material, is actually a process that involves a lot of water, 2,700 liters per shirt to be exact.Take a look at the video below from National Geographic for some more mind-blowing statistics about cotton clothing production.','cet4-2023-06-1-section-2') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
