INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-06-1-section-5-sentence-7-1','cet4-2023-06-1',406,0,'Ambitious people tend to be more materialistically successful than their non-ambitious counterparts.','cet4-2023-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-06-1-section-5-sentence-7-2','cet4-2023-06-1',406,1,'However, they''re only slightly happier than their less-ambitious counterparts, and tend to live significantly shorter lives.','cet4-2023-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-06-1-section-5-sentence-7-3','cet4-2023-06-1',406,2,'This implies that even though ambitious people are more likely to achieve conventional "success," such success means nothing for their health and happiness-and if you don''t have health and happiness, what else could possibly matter?','cet4-2023-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-06-1-section-5-sentence-8-1','cet4-2023-06-1',407,0,'Clearly, some amount of ambition is good for your motivation.','cet4-2023-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-06-1-section-5-sentence-8-2','cet4-2023-06-1',407,1,'Without any ambition, you wouldn''t start your own business, set or achieve goals and get far in life.','cet4-2023-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2023-06-1-section-5-sentence-8-3','cet4-2023-06-1',407,2,'But an excess of ambition can also be dangerous, putting you at risk of burnout, stubbornness and even a shorter life.','cet4-2023-06-1-section-5') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2023-06-1-section-6','cet4-2023-06-1',5,'translation','翻译 · 汉译英','For this part, you are allowed 30 minutes to translate a passage from Chinese into English. You should write your answer on Answer Sheet 2.','["中国越来越重视终身教育,发展继续教育是构建终身教育体系的有效途径。高校作为人才培养的基地,拥有先进的教学理念和优越的教学资源,理应成为继续教育的办学主体。因此,近年来许多高校适应社会需求,加强与用人单位沟通，努力探索一条符合中国国情的继续教育发展新路,以使继续教育在国家发展战略中发挥更大的作用。"]','[]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
