INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2023-06-2-section-1','cet4-2023-06-2',0,'writing','写作','Part I · Writing · 30 minutes','[]','["Suppose the student union of your university is organizing an online discussion on interpersonal relationships. You are to write an essay on ways to maintain a warm and friendly relationship with your classmates and on the benefits of such a relationship. You will have 30 minutes for the task. You should write at least 120 words but no more than 180 words."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
