INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-06-1-section-4-sentence-4-3','cet4-2024-06-1',303,2,'We need to understand that when we desperately want someone to approve of us, it''s being driven by that little kid part of us that is still terrified of abandonment.','cet4-2024-06-1-section-4') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
