INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('cet4-2024-12-1-section-1','cet4-2024-12-1',0,'writing','写作','Part I · Writing · 30 minutes','[]','["Suppose the business school of your university is conducting a survey to collect students'' opinions on the express delivery service industry in China. You are to write a response about its recent development and its impact on people''s lives. You will have 30 minutes to write the essav. You should write at least 120 words but no more than 180 words."]') ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,kind=EXCLUDED.kind,title=EXCLUDED.title,instructions=EXCLUDED.instructions,paragraphs_json=EXCLUDED.paragraphs_json,study_paragraphs_json=EXCLUDED.study_paragraphs_json;
