INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-4-1','cet4-2024-12-2',203,0,'Environmental campaigners are struggling to understand why nations blessed with clean tap water grow only fonder of the bottle.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-4-2','cet4-2024-12-2',203,1,'"It''s very surprising to me," says Sam Chetan-Walsh, a political adviser at Greenpeace and campaigner against ocean plastic.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-4-3','cet4-2024-12-2',203,2,'“Public awareness has never been higher, but the message is not quite reaching all the people it needs to.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-4-4','cet4-2024-12-2',203,3,'"Where it is heard, the message is causing concern.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-4-5','cet4-2024-12-2',203,4,'Plastic water bottles require oceans of fossil fuels to make and ship.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-4-6','cet4-2024-12-2',203,5,'Additionally, single-use plastics of all types are polluting our cities and seas.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-4-7','cet4-2024-12-2',203,6,'Numerous documentaries have shown how plastic is ultimately killing wildlife.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-5-1','cet4-2024-12-2',204,0,'Moves against various plastics have gathered pace, from shopping bags to straws and plastic-lined coffee cups.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-5-2','cet4-2024-12-2',204,1,'Chetan-Walsh argues that bottled water is different because the alternatives are so obvious.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-5-3','cet4-2024-12-2',204,2,'"If a product that is so nakedly unnecessary can exist, then the whole system is failing," he says.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-6-1','cet4-2024-12-2',205,0,'Hope is not entirely out of reach.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-6-2','cet4-2024-12-2',205,1,'The rate of growth has begun to ease (sales were up 7% in the year, compared with 8% the previous year).','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-7-1','cet4-2024-12-2',206,0,'But even if large numbers of people are quitting bottled water because of care for the environment, others are taking it up.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-7-2','cet4-2024-12-2',206,1,'The introduction of the"sugar tax"on juices and soda drinks has pushed more people to bottled water, while health awareness has boosted its desirability.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-7-3','cet4-2024-12-2',206,2,'Tap water consumption is growing at roughly the same pace (UK consumers still drink almost three times as much tap water as bottled water).','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-8-1','cet4-2024-12-2',207,0,'So the plastic tide only creeps higher.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-8-2','cet4-2024-12-2',207,1,'The industry is quick to point out that all its bottles are recyclable.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-8-3','cet4-2024-12-2',207,2,'“But collection rates are, at the most generous estimates,56%, so the actual recycling rate will be lower than that, "Chetan-Walsh says.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-8-4','cet4-2024-12-2',207,3,'And while bottles may be recyclable, very few are made of recycled plastic.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-8-5','cet4-2024-12-2',207,4,'One water bottle company launched recycled half-litre "eco"bottles alongside its standard bottles.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-8-6','cet4-2024-12-2',207,5,'Another has pledged to use only recycled plastic across its range by 2025.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-8-7','cet4-2024-12-2',207,6,'Chetan-Walsh believes in a ban on single-use bottles.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-8-8','cet4-2024-12-2',207,7,'Bans do exist in some places.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-8-9','cet4-2024-12-2',207,8,'Organisers of a famous music festival announced that water bottles will not be sold this summer.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-8-10','cet4-2024-12-2',207,9,'San Francisco has banned them from city property and events.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-8-11','cet4-2024-12-2',207,10,'Last year, the UK government set out plans to ban single-use plastic from its estate.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-9-1','cet4-2024-12-2',208,0,'Water bottlers, unsurprisingly, don''t support bans.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-9-2','cet4-2024-12-2',208,1,'But they raise concerns about health rather than profit margins.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-9-3','cet4-2024-12-2',208,2,'Last month one chief executive of a water botling company said that bans would "result in greater consumption of sugary drinks, adding to all the health dangers of obesity, diabetes and tooth decay".','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-9-4','cet4-2024-12-2',208,3,'Kinvara Carey, general manager of an association of the biggest bottled water manufacturers, cites a survey in which people were asked what they would do if bottled water were not available.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-9-5','cet4-2024-12-2',208,4,'"Forty-four per cent would buy another drink, which is not great,14% would go without and 4.5% said they would find a fountain," she says.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-9-6','cet4-2024-12-2',208,5,'“The choice is important.”','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-10-1','cet4-2024-12-2',209,0,'What if fountains were more numerous, and tap water more clearly available in cafes, restaurants and elsewhere?','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-10-2','cet4-2024-12-2',209,1,'Dozens of fountains are being installed in London.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-10-3','cet4-2024-12-2',209,2,'There are similar initiatives elsewhere.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-10-4','cet4-2024-12-2',209,3,'Before plastic and the marketing that made people think they needed bottled water in the first place, fountains were an urban fixture.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-10-5','cet4-2024-12-2',209,4,'Greenpeace, among others, is also pushing for a"deposit return"scheme.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-10-6','cet4-2024-12-2',209,5,'This would mean tax on bottled water would be refunded to customers who returned the plastic for recycling.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-11-1','cet4-2024-12-2',210,0,'Even if bottled water sales are growing slightly more slowly, the industry is racing to adapt to changing concerns and tastes.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-11-2','cet4-2024-12-2',210,1,'Flavoured water is booming: sales of the sparkling variety shot up by 20%, according to the latest analyst data.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-11-3','cet4-2024-12-2',210,2,'Meanwhile, international water brands, as well as a range of new companies, are selling high-end reusable bottles.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-11-4','cet4-2024-12-2',210,3,'And if you must fill them with tap water, why not add flavouring?','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-12-1','cet4-2024-12-2',211,0,'As the owner of multiple sugary drink brands and bottled water, PepsiCo is facing challenges on health and environmental fronts.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-12-2','cet4-2024-12-2',211,1,'Last year, the company bought SodaStream (a drinks company that sells machines for making tap water bubbly and then consumers add flavours) for $3.2 billion.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-12-3','cet4-2024-12-2',211,2,'It also launched a range of fancy bottles that work with tap water and flavour packets.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-12-4','cet4-2024-12-2',211,3,'The bottle is reusable.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-12-5','cet4-2024-12-2',211,4,'The packets?','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-12-6','cet4-2024-12-2',211,5,'Not so much, and, yes, they are made of plastic, although the company invites users to post them back for recycling','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-13-1','cet4-2024-12-2',212,0,'As is so often the case, clever marketing can beat reason; awareness is rarely enough.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2024-12-2-section-3-sentence-13-2','cet4-2024-12-2',212,1,'“There is always this kind of slip between concern, intent and changed behaviour," says Giles Quick, an analyst of bottled water.','cet4-2024-12-2-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
