INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('cet4-2025-06-1-section-2-q-28','cet4-2025-06-1-section-2',2,'choice','28. 第 28 空','[{"key":"A","text":"accepted"},{"key":"B","text":"audiences"},{"key":"C","text":"building"},{"key":"D","text":"complex"},{"key":"E","text":"constitutes"},{"key":"F","text":"deputies"},{"key":"G","text":"previously"},{"key":"H","text":"revolving"},{"key":"I","text":"samples"},{"key":"J","text":"selected"},{"key":"K","text":"solemn"},{"key":"L","text":"struggle"},{"key":"M","text":"suddenly"},{"key":"N","text":"understand"},{"key":"O","text":"vary"}]','A','参考答案 A，依据原文整理。be accepted by those they admire 表示希望得到自己钦佩的人的认可。',2) ON CONFLICT (id) DO UPDATE SET position=EXCLUDED.position,type=EXCLUDED.type,prompt=EXCLUDED.prompt,options_json=EXCLUDED.options_json,answer_text=EXCLUDED.answer_text,explanation=EXCLUDED.explanation,points=EXCLUDED.points;
