INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('cet4-2025-12-3-section-3-sentence-12-4','cet4-2025-12-3',211,3,'Any and all “"training," including inexpensive and informal training, is going to help resolve their worries about hiring someone over 45.','cet4-2025-12-3-section-3') ON CONFLICT (id) DO UPDATE SET paragraph_index=EXCLUDED.paragraph_index,sentence_index=EXCLUDED.sentence_index,source_text=EXCLUDED.source_text,section_id=EXCLUDED.section_id;
